_rate_reasons = {'ratelimitexceeded', 'userratelimitexceeded', 'rate_limit_exceeded', 'user_rate_limit_exceeded'}

def _error_items(err, key):
    raw = err.raw
    error = raw.get('error') if isinstance(raw, dict) else None
    items = error.get(key) if isinstance(error, dict) else None
    return [o for o in items if isinstance(o, dict)] if isinstance(items, list) else []

def _error_details(err, name):
    return [o for o in _error_items(err, 'details') if o.get('@type') == f'type.googleapis.com/google.rpc.{name}']

def _retryable(err):
    reasons = [o.get('reason') for o in _error_items(err, 'errors') + _error_details(err, 'ErrorInfo')]
    return err.retryable or any(isinstance(r, str) and r.casefold() in _rate_reasons for r in reasons)

