def _number(value):
    try:
        res = float(value)
        if math.isfinite(res): return res
    except (TypeError, ValueError, OverflowError): pass

def _retry_after(err, now):
    if err.response is None: return
    value = err.response.headers.get('retry-after')
    if not value: return
    seconds = _number(value)
    if seconds is not None: return seconds if seconds >= 0 else None
    try:
        when = parsedate_to_datetime(value)
        if when.tzinfo is None: when = when.replace(tzinfo=timezone.utc)
        return max(0, when.timestamp() - now)
    except (TypeError, ValueError, OverflowError): return

# %% ../nbs/00_core.ipynb #052ea42e
_period_secs = dict(s=1, min=60, h=3600, d=86400)

def _retry_info(err):
    waits = []
    for info in _error_details(err, 'RetryInfo'):
        value = info.get('retryDelay')
        m = re.fullmatch(r'(\d+(?:\.\d{1,9})?)s', value) if isinstance(value, str) else None
        wait = _number(m[1]) if m else None
        if wait is not None: waits.append(wait)
    return max(waits, default=None)

def _quota_wait(err, now):
    waits = []
    for info in _error_details(err, 'ErrorInfo'):
        meta = info.get('metadata')
        if not isinstance(meta, dict): continue
        unit = meta.get('quota_unit')
        m = re.fullmatch(r'[1-9]\d*/(\d*)(s|min|h|d)(?:/.*)?', unit) if isinstance(unit, str) else None
        period = _number(m[1] or 1) if m else None
        start = _number(meta.get('window_start_time'))
        if not period or start is None: continue
        end = _number(start + period * _period_secs[m[2]])
        if end is not None: waits.append(max(0, end - now) + 1)
    return max(waits, default=None)

# %% ../nbs/00_core.ipynb #15c829f6
def _retry_delay(err, attempt, base, max_backoff, max_wait=300.0, now=None):
    now = time.time() if now is None else now
    delay = _retry_after(err, now)
    if delay is None: delay = _retry_info(err)
    if delay is None: delay = _quota_wait(err, now)
    if delay is None: delay = min(max_backoff, base*2**attempt) + random.uniform(0, base)
    return delay if delay <= max_wait else None


# %% ../nbs/00_core.ipynb #f45206ac
def _retry_action(err, attempt, n_retries, can_refresh, base=1.0, max_backoff=64.0, max_wait=300.0):
    if attempt == n_retries-1: return 'stop',None
    if err.status_code == 401 and can_refresh: return 'refresh',None
    if not _retryable(err): return 'stop',None
    delay = _retry_delay(err, attempt, base, max_backoff, max_wait)
    return ('stop', None) if delay is None else ('wait', delay)

