@patch
@delegates(AsyncTransport.request)
async def request(
    self:GWSTransport, *args, raw=False,
    n_retries=5, # Maximum attempts, including the initial request
    base=1.0, # Initial exponential backoff and jitter range, in seconds
    max_backoff=64.0, # Maximum exponential component, in seconds
    max_wait=300.0, # Maximum individual retry wait, in seconds
    **kwargs
):
    if n_retries < 1: raise ValueError('n_retries must be at least 1')
    if not math.isfinite(max_wait) or max_wait < 0: raise ValueError('max_wait must be finite and non-negative')
    refreshed = False
    for attempt in range(n_retries):
        try:
            if self.creds and not self.creds.valid: await refresh_creds(self.creds)
            res = await super(GWSTransport, self).request(*args, raw=raw, **kwargs)
            return res if raw else g2obj(res, self.gcls)
        except (httpx2.HTTPStatusError, httpx2.RequestError) as e:
            can_refresh = self.creds and not refreshed
            action,delay = _retry_action(e.api_error(), attempt, n_retries, can_refresh, base, max_backoff, max_wait)
            if action == 'stop': raise
            if action == 'refresh':
                refreshed = True
                await refresh_creds(self.creds)
            else: await asyncio.sleep(delay)

