def request_bytes(request):
    "Serialize a buffered `httpx2.Request` as HTTP/1.1"
    conn = h11.Connection(h11.CLIENT)
    head = h11.Request(method=request.method, target=request.url.raw_path, headers=request.headers.raw)
    return conn.send(head) + conn.send(h11.Data(data=request.content)) + conn.send(h11.EndOfMessage())

def response_from_bytes(data, request):
    "Parse one complete HTTP response for `request`; raise `h11.RemoteProtocolError` for invalid framing"
    conn = h11.Connection(h11.CLIENT)
    conn.send(h11.Request(method=request.method, target=request.url.raw_path, headers=[(b'Host', request.url.netloc)]))
    conn.send(h11.EndOfMessage())
    conn.receive_data(data)
    conn.receive_data(b'')
    response,body = None,[]
    while True:
        event = conn.next_event()
        if isinstance(event, h11.Response): response = event
        elif isinstance(event, h11.Data): body.append(event.data)
        elif isinstance(event, h11.EndOfMessage): break
        elif isinstance(event, h11.InformationalResponse) and event.status_code != 101: continue
        else: raise h11.RemoteProtocolError('Incomplete HTTP response')
    if response is None or conn.trailing_data[0]: raise h11.RemoteProtocolError('Expected one complete HTTP response')
    return httpx2.Response(response.status_code, headers=response.headers, content=b''.join(body), request=request,
        extensions={'http_version':b'HTTP/' + response.http_version, 'reason_phrase':response.reason})

