@patch
def _batch_results(self:GWSOpFunc, response, requests):
    ctype = response.headers.get('content-type')
    if not ctype: raise ValueError('Google batch response has no Content-Type')
    prefix = f'Content-Type: {ctype}\r\n\r\n'.encode()
    msg = BytesParser(policy=email_policy.clone(raise_on_defect=True)).parsebytes(prefix + response.content)
    if msg.get_content_type() != 'multipart/mixed': raise ValueError('Google batch response must be multipart/mixed')
    parts = list(msg.iter_parts())
    if len(parts) != len(requests): raise ValueError(f'Google batch returned {len(parts)} parts for {len(requests)} calls')
    results = []
    for part,request in zip(parts, requests):
        if part.get_content_type() != 'application/http': raise ValueError('Google batch parts must be application/http')
        inner = response_from_bytes(part.get_payload(decode=True), request)
        try: inner.raise_for_status()
        except httpx2.HTTPStatusError as e:
            err = e.api_error(endpoint=f'{request.method} {request.url.path}')
            err.retryable = _retryable(err)
            results.append(err)
        else: results.append(g2obj(self.client._decode(inner), self.client.gcls))
    return results

