@patch
async def _batch_once(self:GWSOpFunc, calls, n_retries, base, max_backoff, max_wait):
    boundary = f'fastgws_{uuid4().hex}'
    content,requests = self._batch_content(calls, boundary)
    headers = {'Content-Type':f'multipart/mixed; boundary={boundary}'}
    try:
        response = await self.client.request('POST', self.batch_url, headers=headers, content=content, raw=True,
            n_retries=n_retries, base=base, max_backoff=max_backoff, max_wait=max_wait)
    except Exception as e: self._raise_with_context(e, endpoint=self.batch_url)
    return self._batch_results(response, requests)

