@patch
async def _batch_chunk(self:GWSOpFunc, calls, n_retries, base, max_backoff, max_wait):
    results,pending,refreshed = [None]*len(calls),dict(enumerate(calls)),False
    for attempt in range(n_retries):
        indexes = list(pending)
        values = await self._batch_once([pending[i] for i in indexes], n_retries, base, max_backoff, max_wait)
        retry,refresh,waits = {},False,[]
        for i,value in zip(indexes, values):
            if not isinstance(value, APIError):
                results[i] = value
                continue
            action,delay = _retry_action(value, attempt, n_retries, self.client.creds and not refreshed, base, max_backoff, max_wait)
            if action == 'stop': results[i] = value
            else:
                retry[i] = pending[i]
                if action == 'refresh': refresh = True
                else: waits.append(delay)
        if not retry: break
        if refresh:
            refreshed = True
            await refresh_creds(self.client.creds)
        if waits: await asyncio.sleep(max(waits))
        pending = retry
    return results


