@patch
async def batch(
    self:GWSOpFunc,
    calls, # Dictionaries of operation arguments, in result order
    chunk=50, # Calls per batch request, at most 100
    return_exceptions=False, # Return per-call APIError values instead of raising
    n_retries=5, # Maximum attempts for each batch request and failed part
    base=1.0, # Initial exponential backoff and jitter range, in seconds
    max_backoff=64.0, # Maximum exponential component, in seconds
    max_wait=300.0 # Maximum individual retry wait, in seconds
):
    "Run dictionaries of arguments for this operation through Google's discovery-advertised HTTP batch endpoint"
    if not self.batch_url: raise ValueError('This Google service does not advertise a batch endpoint')
    if not 1 <= chunk <= 100: raise ValueError('chunk must be between 1 and 100')
    if n_retries < 1: raise ValueError('n_retries must be at least 1')
    if not math.isfinite(max_wait) or max_wait < 0: raise ValueError('max_wait must be finite and non-negative')
    calls = list(calls)
    results = []
    for i in range(0, len(calls), chunk): results.extend(await self._batch_chunk(calls[i:i+chunk], n_retries, base, max_backoff, max_wait))
    if not return_exceptions:
        error = first(x for x in results if isinstance(x, APIError))
        if error: raise error
    return results


