@patch
async def pages(self:GWSOpFunc, *args, **kwargs):
    "Yield every page from a Google list operation"
    while True:
        page = await self(*args, **kwargs)
        yield page
        token = page.get('nextPageToken')
        if not token: return
        kwargs['page_token'] = token

